begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(21);
select has_table('private','account_suspensions','Suspension state exists');
select has_table('private','suspension_audit','Suspension audit exists');
select ok((select relrowsecurity from pg_class where oid='private.account_suspensions'::regclass),'State RLS enabled');
select ok((select relrowsecurity from pg_class where oid='private.suspension_audit'::regclass),'Audit RLS enabled');
select is(has_table_privilege('authenticated','private.account_suspensions','SELECT,INSERT,UPDATE,DELETE'),false,'No direct client status access');
select is(has_table_privilege('authenticated','private.suspension_audit','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),false,'No direct client audit access');
select is(has_table_privilege('rollcall_status_executor','private.suspension_audit','UPDATE,DELETE,TRUNCATE'),false,'Executor cannot rewrite audit');
select is(has_table_privilege('rollcall_status_executor','private.account_roles','UPDATE'),false,'Status executor cannot change roles');
select is(has_table_privilege('rollcall_status_executor','private.event_locations','SELECT'),false,'No address grant');
select is(has_table_privilege('rollcall_status_executor','private.event_invitations','SELECT'),false,'No code grant');
select is(has_table_privilege('rollcall_status_executor','private.profile_private','SELECT'),false,'No private age grant');
select is(has_schema_privilege('rollcall_status_executor','auth','USAGE'),false,'No raw Auth access');
select is(pg_has_role('authenticated','rollcall_status_executor','MEMBER'),false,'Clients cannot assume executor');
select is((select rolcanlogin from pg_roles where rolname='rollcall_status_executor'),false,'Executor cannot log in');
select is((select rolbypassrls from pg_roles where rolname='rollcall_status_executor'),false,'Executor cannot bypass RLS');
select is(has_function_privilege('anon','public.change_account_suspension(uuid,boolean,text)','EXECUTE'),false,'Anonymous changes denied');
select is(has_function_privilege('authenticated','private.account_status_actor()','EXECUTE'),false,'Raw identity helper is internal');
select is((select provolatile::text from pg_proc where oid='private.require_active_account()'::regprocedure),'v','Live status guard uses fresh snapshots');
select ok((select prosrc like '%require_active_account%' from pg_proc where oid='public.create_event(jsonb)'::regprocedure),'Event entry guards before locks');
select ok((select prosrc like '%require_active_account%' from pg_proc where oid='public.update_my_profile(jsonb)'::regprocedure),'Profile RPC guarded');
select throws_ok('truncate private.suspension_audit','42501','Role audit is append-only.','Audit truncate rejected');
select * from finish();
rollback;
